insert into public.quiz_item (id, kp, kind, level, body, src, status) values
  ('pro-where-1', 'pro-where', 'mc', 1, '{"q":"隔著臺灣海峽，在臺灣西邊的是哪裡？","opts":["中國大陸","菲律賓","日本"],"a":0,"why":"臺灣西邊隔著臺灣海峽是中國大陸；菲律賓在南邊，日本在東北邊。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉', 'draft'),
  ('pro-where-2', 'pro-where', 'tf', 1, '{"q":"臺灣的東邊是一大片太平洋。","a":true,"why":"臺灣東邊面對太平洋，西邊是臺灣海峽。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉', 'draft'),
  ('pro-where-3', 'pro-where', 'cat', 2, '{"q":"把臺灣的鄰居放到正確的方向。","cats":["北邊、東北邊","南邊","西邊"],"cards":[{"t":"日本","c":0},{"t":"琉球群島","c":0},{"t":"菲律賓","c":1},{"t":"中國大陸","c":2}],"why":"日本、琉球在臺灣的東北邊；菲律賓在南邊，隔著巴士海峽；中國大陸在西邊，隔著臺灣海峽。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉', 'draft'),
  ('pro-wind-1', 'pro-wind', 'cloze', 1, '{"q":"選出正確的季風。","text":"臺灣冬天吹{0}，夏天吹{1}。","blanks":[{"opts":["東北季風","西南季風"],"a":0},{"opts":["東北季風","西南季風"],"a":1}],"why":"冬天的風從東北邊吹來，夏天的風從西南邊吹來，方向剛好相反。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-wind-2', 'pro-wind', 'tf', 1, '{"q":"黑潮是一道在臺灣東邊、往北流的海流。","a":true,"why":"黑潮從南邊流過臺灣東邊的海，一路往北流。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-wind-3', 'pro-wind', 'who', 2, '{"q":"從前的人坐帆船出海，誰的想法比較有道理？","says":[{"n":"阿明","t":"什麼時候出發都一樣，划快一點就好"},{"n":"小華","t":"要看季風和海流，順著風走比較省力"},{"n":"阿美","t":"一定要等沒有風的日子才能出發"}],"a":1,"why":"帆船靠風推動，從前的人會看季風和海流的方向，決定出發的季節。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-land-1', 'pro-land', 'mc', 1, '{"q":"臺灣最高的山是哪一座？","opts":["阿里山","玉山","陽明山"],"a":1,"why":"玉山是臺灣最高的山，在中央山脈附近。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-land-2', 'pro-land', 'mc', 2, '{"q":"臺灣的平原大多在哪一邊？","opts":["東部","西部","中央"],"a":1,"why":"臺灣中間有高高的中央山脈，平原大多在西部。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-land-3', 'pro-land', 'multi', 2, '{"q":"早期的人喜歡在哪樣的地方蓋村莊？（選兩個）","opts":["地勢平坦的平原","靠近河流、方便取水","很高很陡的山頂","四周都沒有水的地方"],"a":[0,1],"why":"平原平坦好種田，靠近河流可以取水，所以很多村莊蓋在平原和河邊。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-tropic-1', 'pro-tropic', 'mc', 1, '{"q":"北回歸線經過臺灣的哪兩個地方？","opts":["嘉義和花蓮","臺北和宜蘭","高雄和屏東"],"a":0,"why":"北回歸線經過嘉義和花蓮，兩地都有北回歸線的地標。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-tropic-2', 'pro-tropic', 'tf', 2, '{"q":"北回歸線的南邊是熱帶，所以臺灣南部通常比北部熱。","a":true,"why":"北回歸線以南是熱帶、以北是亞熱帶，南部比較熱。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-rain-1', 'pro-rain', 'mc', 2, '{"q":"冬天常常下雨的是哪裡？","opts":["基隆、宜蘭","臺南、高雄","澎湖、金門"],"a":0,"why":"冬天東北季風帶著海上的水氣，碰到東北部的山就下雨，所以基隆、宜蘭冬天多雨。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-rain-2', 'pro-rain', 'order', 3, '{"q":"排出「基隆冬天下雨」的順序。","steps":["東北季風吹過海面","風帶著很多水氣","碰到臺灣東北部的山","水氣變成雨落下來"],"why":"季風經過海面帶走水氣，被山擋住往上爬，水氣變冷就下成雨。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('ch1-tools-1', 'ch1-tools', 'tf', 1, '{"q":"磨製石器是加水和砂慢慢磨出來的，表面比較光滑。","a":true,"why":"磨製石器先敲出形狀，再在磨石上加水和砂磨，所以又光滑又鋒利。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-tools-2', 'ch1-tools', 'cat', 2, '{"q":"這些工具是怎麼做出來的？","cats":["打製","磨製"],"cards":[{"t":"長濱文化的砍砸器","c":0},{"t":"卑南文化的石錛","c":1},{"t":"邊緣粗粗的石片","c":0},{"t":"光滑的石刀","c":1}],"why":"長濱文化用敲打做成的打製石器；後來的新石器時代會再磨，做成光滑的磨製石器。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-tools-3', 'ch1-tools', 'mc', 2, '{"q":"做磨製石器，比做打製石器多了哪一個步驟？","opts":["把石頭敲出形狀","在磨石上加水和砂慢慢磨","把石頭丟進火裡燒"],"a":1,"why":"兩種都要先敲出大概的樣子，磨製石器還要再磨。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-pottery-1', 'ch1-pottery', 'mc', 1, '{"q":"大坌坑文化的陶器上，常常有什麼紋路？","opts":["用繩子拍出來的紋路","用筆畫的山水","用金子貼的花"],"a":0,"why":"大坌坑文化的陶器常有繩子拍出的紋路，叫粗繩紋陶。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-pottery-2', 'ch1-pottery', 'who', 2, '{"q":"人們開始種植、住下來以後，為什麼需要陶器？誰說得對？","says":[{"n":"小安","t":"可以煮東西，也能存放收成和水"},{"n":"阿傑","t":"因為陶器可以拿來打獵"},{"n":"小芳","t":"因為搬家時陶器最輕"}],"a":0,"why":"住下來、有了收成，就要把食物煮熟、把糧食和水存起來，陶罐就很重要。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-pottery-3', 'ch1-pottery', 'tf', 2, '{"q":"長濱文化的人已經會種田、做陶器。","a":false,"why":"長濱文化是舊石器時代，人們住在海邊山洞，靠採集、打獵、捕魚，還不會種田和做陶器。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-strata-1', 'ch1-strata', 'mc', 2, '{"q":"考古學家在同一個地方挖到上下兩層土，通常哪一層比較古老？","opts":["上面那一層","下面那一層","兩層一樣老"],"a":1,"why":"土一層一層往上堆，壓在下面的通常比較早堆積。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-strata-2', 'ch1-strata', 'tf', 1, '{"q":"沒有文字的史前時代，要靠考古挖掘和研究器物，才知道當時人怎麼生活。","a":true,"why":"史前時代沒有文字紀錄，所以要靠遺址和留下來的器物。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-cultures-1', 'ch1-cultures', 'order', 2, '{"q":"把這些史前文化，從最早排到最晚。","steps":["長濱文化","大坌坑文化","卑南文化","十三行文化"],"why":"長濱是舊石器時代，大坌坑是新石器早期，卑南是新石器時代，十三行是金屬器時代。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-cultures-2', 'ch1-cultures', 'mc', 1, '{"q":"會煉鐵、還挖到外來琉璃珠的，是哪一個史前文化？","opts":["長濱文化","卑南文化","十三行文化"],"a":2,"why":"十三行文化在新北八里，已經會煉鐵，也和外地人交換東西。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-cultures-3', 'ch1-cultures', 'mc', 1, '{"q":"用石板蓋房子、做精美玉器的，是哪一個史前文化？","opts":["卑南文化","長濱文化","大坌坑文化"],"a":0,"why":"卑南文化在臺東，有石板屋、石板棺和玉器。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch2-fallow-1', 'ch2-fallow', 'tf', 2, '{"q":"一塊田種了幾年後讓它休息，土地的肥力會慢慢回來。","a":true,"why":"作物會用掉土裡的養分，讓田休息長草，養分慢慢恢復。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-fallow-2', 'ch2-fallow', 'who', 2, '{"q":"部落的田為什麼要輪流休耕？誰說得對？","says":[{"n":"阿妮","t":"讓土地休息，肥力回來，以後才能一直有收成"},{"n":"大雄","t":"因為大家想休假，不想種田"},{"n":"小美","t":"因為休耕的田看起來比較漂亮"}],"a":0,"why":"輪耕和休耕讓土地休養，才能長長久久地種下去。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-fallow-3', 'ch2-fallow', 'mc', 1, '{"q":"很多原住民族種的小米，有什麼特點？","opts":["很耐旱，適合種在山坡上","一定要泡在水裡才能長","只能種在海邊沙灘"],"a":0,"why":"小米耐旱，適合山坡；很多祭儀也跟著小米的播種和收成安排。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-hunt-1', 'ch2-hunt', 'multi', 2, '{"q":"部落打獵常有哪些規矩？（可以選很多個）","opts":["有些季節不打獵","不打懷孕的母獸和小動物","不闖進別人的獵場","看到什麼就全部打光"],"a":[0,1,2],"why":"這些規矩讓動物可以一直繁衍，也讓部落之間不起衝突。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-hunt-2', 'ch2-hunt', 'mc', 2, '{"q":"春天不打獵，主要是為了什麼？","opts":["春天下雨，路太滑","讓母鹿安心生小鹿，鹿群才能延續","春天的鹿肉比較不好吃"],"a":1,"why":"春天是動物繁殖的季節，不打獵才能讓鹿群一直延續下去。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-norms-1', 'ch2-norms', 'tf', 2, '{"q":"部落的規範，很多是從和自然相處的經驗，一代一代累積下來的。","a":true,"why":"祖先觀察山林、經歷過缺糧，慢慢累積成大家要遵守的規矩。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-norms-2', 'ch2-norms', 'mc', 2, '{"q":"打到的獵物、收成的小米分給大家，對部落有什麼幫助？","opts":["讓每一家都有得吃，一起度過難關","讓打獵的人以後不用再出門","讓山上的獵物馬上變得更多"],"a":0,"why":"分享讓部落互相照顧，碰到壞年冬也能一起撐過去。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-peoples-1', 'ch2-peoples', 'mc', 1, '{"q":"臺灣原住民族屬於哪一個語族？","opts":["南島語族","日耳曼語族","漢藏語族"],"a":0,"why":"臺灣原住民族屬於南島語族，分布在太平洋和印度洋的很多島嶼。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-peoples-2', 'ch2-peoples', 'who', 2, '{"q":"關於臺灣的原住民族，誰說得對？","says":[{"n":"小凱","t":"原住民族只有一族，大家說一樣的話"},{"n":"阿妮","t":"政府認定的有 16 族，每一族有自己的語言和祭儀"},{"n":"小玲","t":"原住民族全部都住在海邊"}],"a":1,"why":"目前政府認定 16 族，各族的語言、服飾、祭儀和生活都不一樣。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch3-entrepot-1', 'ch3-entrepot', 'tf', 2, '{"q":"轉口貿易是把貨先運到一個港口，再轉運到別的地方賣。","a":true,"why":"中國的生絲、瓷器經過大員，再運到日本、南洋和歐洲。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-entrepot-2', 'ch3-entrepot', 'mc', 3, '{"q":"大員能成為轉運站，最主要是因為什麼？","opts":["剛好在中國、日本、南洋航線的中間","那裡的東西全部都最便宜","只有大員有港口"],"a":0,"why":"臺灣在東亞航線的中間，船可以在大員換貨、轉運。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-entrepot-3', 'ch3-entrepot', 'mc', 1, '{"q":"荷蘭人來到大員，是哪一個組織派來做生意的？","opts":["荷蘭東印度公司","英國的洋行","清朝的水師"],"a":0,"why":"荷蘭東印度公司總部在巴達維亞，大員是它在東亞的據點。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-monsoon-1', 'ch3-monsoon', 'cloze', 2, '{"q":"從大員坐帆船去日本。","text":"往北去日本，最好等{0}吹西南季風時出發；回來時，等{1}吹東北季風。","blanks":[{"opts":["夏天","冬天"],"a":0},{"opts":["夏天","冬天"],"a":1}],"why":"夏天的西南季風往東北吹，帆船順風往北；冬天的東北季風往西南吹，正好回程。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-monsoon-2', 'ch3-monsoon', 'tf', 2, '{"q":"從前的帆船去日本，冬天出發最順。","a":false,"why":"冬天吹東北季風，是逆風；去日本要等夏天的西南季風。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-sinkan-1', 'ch3-sinkan', 'mc', 1, '{"q":"新港文書是用什麼文字寫的？","opts":["用羅馬字拼寫西拉雅語","漢字","日文假名"],"a":0,"why":"傳教士教西拉雅族人用羅馬字拼寫自己的語言。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-sinkan-2', 'ch3-sinkan', 'tf', 2, '{"q":"荷蘭人離開以後，西拉雅族人還用羅馬字寫土地契約。","a":true,"why":"荷蘭人走後，他們還繼續用這種文字寫契約，留下很多新港文書。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-timeline-1', 'ch3-timeline', 'order', 2, '{"q":"把這些事情照發生的先後排好。","steps":["荷蘭人來到大員","西班牙人在基隆蓋城堡","荷蘭人趕走西班牙人","鄭成功讓荷蘭人離開臺灣"],"why":"1624 荷蘭人到大員，1626 西班牙人到基隆，1642 荷蘭人趕走西班牙人，1662 鄭成功讓荷蘭人離開。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-timeline-2', 'ch3-timeline', 'mc', 1, '{"q":"荷蘭人在大員蓋的城堡叫什麼？今天在那裡的是安平古堡。","opts":["熱蘭遮城","聖薩爾瓦多城","紅毛城"],"a":0,"why":"熱蘭遮城在大員（臺南安平）；聖薩爾瓦多城是西班牙人在基隆蓋的。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-timeline-3', 'ch3-timeline', 'mc', 1, '{"q":"西班牙人在北臺灣蓋城堡，主要在哪裡？","opts":["基隆和淡水","臺南和高雄","花蓮和臺東"],"a":0,"why":"西班牙人從菲律賓北上，在基隆、淡水蓋城堡、傳教。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-goods-1', 'ch3-goods', 'mc', 1, '{"q":"荷蘭時期，臺灣的鹿皮大多賣到哪裡？","opts":["日本","美國","澳洲"],"a":0,"why":"鹿皮大多賣到日本，做武士的盔甲和衣物。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-goods-2', 'ch3-goods', 'who', 2, '{"q":"荷蘭時期每年運走好幾萬張鹿皮，結果會怎樣？誰說得對？","says":[{"n":"阿福","t":"鹿會越來越少"},{"n":"小真","t":"鹿會越來越多"},{"n":"大衛","t":"鹿的數量不會改變"}],"a":0,"why":"大量捕鹿賣皮，鹿生得比被捕的少，就越來越少。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-goods-3', 'ch3-goods', 'tf', 1, '{"q":"荷蘭人招募從福建來的漢人種甘蔗、做糖。","a":true,"why":"蔗糖是荷蘭時期重要的出口貨，種甘蔗的多是渡海來的漢人。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-tuntian-1', 'ch4-tuntian', 'mc', 2, '{"q":"「寓兵於農」的兵，平常在做什麼？","opts":["種田，要打仗時再上戰場","一直在練習射箭","在城裡賣東西"],"a":0,"why":"軍隊平常分到各地開墾種田，自己生產糧食。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-tuntian-2', 'ch4-tuntian', 'multi', 2, '{"q":"哪些地名是從鄭氏時期軍隊屯田紮營留下來的？（選兩個以上）","opts":["新營","左營","林鳳營","淡水"],"a":[0,1,2],"why":"新營、柳營、林鳳營、左營都和軍隊紮營有關；淡水是河口的地名。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-tuntian-3', 'ch4-tuntian', 'tf', 3, '{"q":"軍隊自己種糧食，就不用一直從海上運米來。","a":true,"why":"屯田讓軍隊自給自足，也把很多荒地開成田。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-pond-1', 'ch4-pond', 'mc', 2, '{"q":"臺南一帶挖水埤，主要是為了什麼？","opts":["把雨季的水存起來，旱季拿來灌溉","挖成游泳池，讓大家夏天玩水","在港口前面擋住外國的船"],"a":0,"why":"臺南雨季、旱季很分明，有埤就能在旱季灌溉。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-pond-2', 'ch4-pond', 'who', 3, '{"q":"一個地方夏天雨很多、冬天幾乎不下雨，誰的辦法最好？","says":[{"n":"小蓮","t":"挖一個埤，把夏天的水存起來"},{"n":"阿忠","t":"冬天不要種任何東西"},{"n":"小慧","t":"把河填平，田就不會淹水"}],"a":0,"why":"把多的雨水存起來，到缺水的時候再用，就是水埤的道理。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-school-1', 'ch4-school', 'mc', 1, '{"q":"被叫做「全臺首學」的是哪裡？","opts":["臺南孔廟","臺北101","熱蘭遮城"],"a":0,"why":"1666 年建成的臺南孔廟是臺灣第一座孔廟，旁邊設學校。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-school-2', 'ch4-school', 'tf', 1, '{"q":"臺南孔廟是臺灣第一座孔廟。","a":true,"why":"它在 1666 年建成，所以叫全臺首學。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-salt-1', 'ch4-salt', 'mc', 2, '{"q":"陳永華教人「曬鹽」，比原本的「煎鹽」好在哪裡？","opts":["用太陽曬，省下很多柴，鹽也做得更多","曬出來的鹽是甜的，比較好吃","曬鹽不用海水，用河水就可以"],"a":0,"why":"煎鹽要燒柴煮海水；曬鹽用太陽，省柴又做得多。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-salt-2', 'ch4-salt', 'order', 2, '{"q":"排出曬鹽的順序。","steps":["把海水引進鹽田","讓太陽曬，水慢慢蒸發","鹽田裡留下白白的鹽","把鹽收起來"],"why":"海水進鹽田，太陽把水曬乾，留下鹽，再收集起來。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-people-1', 'ch4-people', 'cat', 1, '{"q":"這些人和哪件事有關？","cats":["趕走荷蘭人","推動教育和曬鹽","攻下澎湖、臺灣歸清朝"],"cards":[{"t":"鄭成功","c":0},{"t":"陳永華","c":1},{"t":"施琅","c":2}],"why":"鄭成功 1662 年讓荷蘭人離開；陳永華建孔廟、教曬鹽；施琅 1683 年打下澎湖。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-people-2', 'ch4-people', 'tf', 2, '{"q":"1683 年鄭克塽投降以後，臺灣歸清朝統治。","a":true,"why":"施琅打下澎湖，鄭克塽投降，臺灣歸清朝。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-people-3', 'ch4-people', 'mc', 1, '{"q":"鄭經把臺灣改名叫什麼？","opts":["東寧","大員","福爾摩沙"],"a":0,"why":"鄭經把臺灣改名「東寧」。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch5-flow-1', 'ch5-flow', 'tf', 2, '{"q":"挖水圳要讓圳道慢慢往低的地方走，水才流得過去。","a":true,"why":"水只會往一樣高或更低的地方流。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-flow-2', 'ch5-flow', 'mc', 3, '{"q":"八堡圳的圳頭，為什麼開在上游的二水？","opts":["二水比下游的平原高，水才能一路流進田裡","二水的溪水比較甜，種出來的米比較好吃","二水離海最近，挖好的圳道可以順便行船"],"a":0,"why":"圳頭要比田高，水才能沿著圳道往低處流。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-flow-3', 'ch5-flow', 'mc', 2, '{"q":"地圖上的等高線越密，表示什麼？","opts":["坡越陡","水越深","人越多"],"a":0,"why":"等高線把一樣高的地方連起來，線越密，表示高度變化越快，坡就越陡。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-cage-1', 'ch5-cage', 'mc', 2, '{"q":"竹蛇籠是用什麼做的？","opts":["竹子編成長籠子，裡面裝石頭","鐵打成一扇很重的大門","木頭釘成一艘長長的船"],"a":0,"why":"竹籠裝石頭，一個接一個排在河裡，把水導進圳頭。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-cage-2', 'ch5-cage', 'who', 3, '{"q":"大水來的時候，誰的方法比較不容易被沖壞？","says":[{"n":"阿穆","t":"斜斜地把水導到旁邊"},{"n":"小明","t":"正面蓋一道牆硬擋"},{"n":"阿蓮","t":"什麼都不做"}],"a":0,"why":"順著水把它導開比較省力；正面硬擋，大水的力量全打在牆上。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-fair-1', 'ch5-fair', 'mc', 3, '{"q":"甲村有 6 塊田、乙村有 4 塊田，一起分 10 份水，怎麼分比較公平？","opts":["甲 6 份、乙 4 份","甲 5 份、乙 5 份","先挖到的全部拿走"],"a":0,"why":"照需要分才公平：田多的多分一點。一樣多是「平均」，不一定公平。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-fair-2', 'ch5-fair', 'tf', 2, '{"q":"「平均」分和「公平」分，意思一定一樣。","a":false,"why":"平均是一樣多；公平要看每一邊的需要，兩者不一定相同。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-babao-1', 'ch5-babao', 'mc', 1, '{"q":"八堡圳是從哪一條河引水？","opts":["濁水溪","淡水河","曾文溪"],"a":0,"why":"八堡圳從濁水溪上游的二水引水，灌溉彰化平原。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-babao-2', 'ch5-babao', 'cloze', 1, '{"q":"八堡圳的故事。","text":"{0}從 1709 年開始找人開圳，前後大約花了{1}才完成。","blanks":[{"opts":["施世榜","劉銘傳","八田與一"],"a":0},{"opts":["十年","一個月","一百年"],"a":0}],"why":"施世榜 1709 年開工，大約十年完成；三百多年後還在灌溉彰化的田。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-babao-3', 'ch5-babao', 'tf', 2, '{"q":"八堡圳到今天還在灌溉彰化的田。","a":true,"why":"八堡圳開了三百多年，現在還在用。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch6-tea-1', 'ch6-tea', 'mc', 2, '{"q":"開港以後，大稻埕變熱鬧，主要因為什麼？","opts":["茶葉大量出口，茶行、洋行都聚在這裡","那裡蓋了全臺第一座孔廟","那裡是荷蘭人的城堡"],"a":0,"why":"北部的茶賣到國外，茶行、洋行和碼頭工人都聚到淡水河邊的大稻埕。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-tea-2', 'ch6-tea', 'mc', 1, '{"q":"清末賣到美國很受歡迎的「福爾摩沙茶」是哪一種？","opts":["烏龍茶","紅豆湯","咖啡"],"a":0,"why":"臺灣的烏龍茶賣到美國，被叫做福爾摩沙烏龍茶。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-tea-3', 'ch6-tea', 'order', 3, '{"q":"大稻埕的茶怎麼賣到國外？排出順序。","steps":["山上的茶農採茶","茶送到大稻埕的茶行加工","從淡水港上大船","運到國外賣"],"why":"茶從山上採下，在大稻埕加工，再從淡水港出海。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-rail-1', 'ch6-rail', 'tf', 2, '{"q":"鐵路蓋好以後，人和貨物可以比以前更快運到遠方。","a":true,"why":"火車能載很多人和貨，也不怕河水深淺。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-rail-2', 'ch6-rail', 'mc', 1, '{"q":"基隆到臺北之間的山太陡，火車怎麼過去？","opts":["挖隧道穿過山（獅球嶺隧道）","用纜車把火車吊過山頭","把鐵路繞到海上的橋走"],"a":0,"why":"獅球嶺隧道是臺灣第一座鐵路隧道。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-rail-3', 'ch6-rail', 'mc', 1, '{"q":"清末劉銘傳時代的火車頭，現在還保存在博物館的是哪一輛？","opts":["騰雲號","太魯閣號","普悠瑪號"],"a":0,"why":"騰雲號是當時的火車頭，保存在國立臺灣博物館。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-mackay-1', 'ch6-mackay', 'multi', 2, '{"q":"馬偕在淡水做了哪些事？（選兩個以上）","opts":["學會說臺語","幫人看病、拔牙","辦學堂教新知識","蓋了全臺首學孔廟"],"a":[0,1,2],"why":"馬偕學臺語，開醫館、辦學堂；孔廟是鄭氏時期在臺南蓋的。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-mackay-2', 'ch6-mackay', 'mc', 1, '{"q":"馬偕是從哪一個國家來的？","opts":["加拿大","荷蘭","日本"],"a":0,"why":"馬偕從加拿大來，在淡水住了將近三十年。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-ports-1', 'ch6-ports', 'cat', 2, '{"q":"哪些是清末臺灣的三大出口品？","cats":["三大出口品","不是"],"cards":[{"t":"茶","c":0},{"t":"樟腦","c":0},{"t":"糖","c":0},{"t":"電視機","c":1}],"why":"清末臺灣三大出口品是茶、樟腦和糖。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-ports-2', 'ch6-ports', 'multi', 1, '{"q":"清末開港，臺灣開放了哪些港口？（選兩個以上）","opts":["淡水","基隆","安平","日月潭"],"a":[0,1,2],"why":"開放的是淡水、基隆、安平、打狗四個港口；日月潭是湖。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-ports-3', 'ch6-ports', 'tf', 1, '{"q":"洋行是外國商人開的貿易公司。","a":true,"why":"洋行向臺灣人買茶、樟腦、糖運到國外，也把外國的貨運進來。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-liu-1', 'ch6-liu', 'mc', 1, '{"q":"臺灣建省後的第一任巡撫是誰？","opts":["劉銘傳","鄭成功","馬偕"],"a":0,"why":"劉銘傳是第一任巡撫，推動鐵路、電報、郵政和新式學堂。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-liu-2', 'ch6-liu', 'multi', 2, '{"q":"劉銘傳推動了哪些建設？（選兩個以上）","opts":["鋪鐵路","架電報線","設郵政","蓋高鐵"],"a":[0,1,2],"why":"劉銘傳鋪鐵路、架電報、設郵政；高鐵是 2007 年才通車。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-rotation-1', 'ch7-rotation', 'mc', 2, '{"q":"嘉南大圳的「三年輪作」，把田分成幾區輪流種？","opts":["三區","兩區","十區"],"a":0,"why":"田分成三區，每年輪流種水稻、甘蔗和雜作，三年一輪。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-rotation-2', 'ch7-rotation', 'who', 3, '{"q":"為什麼嘉南平原要三年輪作？誰說得對？","says":[{"n":"阿雄","t":"水不夠讓全部的田同時種稻，輪流才分得夠"},{"n":"小雅","t":"因為農民喜歡每年換種東西"},{"n":"阿德","t":"因為甘蔗不需要土"}],"a":0,"why":"水庫放得出的水有限，輪流種稻，水才夠，每一區也都輪得到。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-railway-1', 'ch7-railway', 'mc', 1, '{"q":"縱貫鐵路全線通車，是從哪裡到哪裡？","opts":["基隆到高雄","臺北到宜蘭","花蓮到臺東"],"a":0,"why":"1908 年縱貫鐵路從基隆通到高雄。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-railway-2', 'ch7-railway', 'tf', 2, '{"q":"縱貫鐵路通車後，南北來往從好多天變成大約一天。","a":true,"why":"火車讓南北往來快很多，米、糖也能很快運到港口。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-twosides-1', 'ch7-twosides', 'who', 3, '{"q":"說到日治時期的建設，誰的看法比較完整？","says":[{"n":"小婷","t":"建設帶來進步，也要看到臺灣人受到不平等對待"},{"n":"阿凱","t":"全部都是好的，沒有壞處"},{"n":"小宇","t":"全部都是壞的，什麼都沒改變"}],"a":0,"why":"建設讓交通、農業進步；但重要的事多由日本政府決定，臺灣人受到不平等對待。兩面都要看見。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-twosides-2', 'ch7-twosides', 'mc', 2, '{"q":"日治時期，臺灣孩子讀的學校叫什麼？","opts":["公學校","小學校","書院"],"a":0,"why":"臺灣孩子讀公學校，日本孩子讀小學校，兩邊的機會不一樣。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-twosides-3', 'ch7-twosides', 'cloze', 1, '{"q":"日治時期。","text":"從{0}年到{1}年，臺灣由日本統治。","blanks":[{"opts":["1895","1683","1945"],"a":0},{"opts":["1945","1895","1662"],"a":0}],"why":"1895 年到 1945 年是日治時期。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-canal-1', 'ch7-canal', 'mc', 1, '{"q":"設計烏山頭水庫和嘉南大圳的工程師是誰？","opts":["八田與一","劉銘傳","施世榜"],"a":0,"why":"八田與一設計了烏山頭水庫和嘉南大圳，1930 年完工。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-canal-2', 'ch7-canal', 'mc', 2, '{"q":"嘉南大圳完成以後，「看天田」有什麼改變？","opts":["有水圳引水，可以穩定耕種","全部改蓋房子","變成鹽田"],"a":0,"why":"看天田只能靠下雨；有了嘉南大圳，就能穩定灌溉。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-canal-3', 'ch7-canal', 'tf', 2, '{"q":"「看天田」是只能靠下雨灌溉的田。","a":true,"why":"沒有水圳的田，雨不來稻子就種不起來。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-sunmoon-1', 'ch7-sunmoon', 'mc', 2, '{"q":"日月潭發電工程讓湖水升高，住在那裡的哪一族失去了家園？","opts":["邵族","達悟族","阿美族"],"a":0,"why":"邵族住在日月潭一帶，湖水升高淹沒了他們的家和田。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-sunmoon-2', 'ch7-sunmoon', 'tf', 1, '{"q":"日月潭發電所是用水從高處沖下來的力量發電。","a":true,"why":"水從高處沖到山下的發電所，帶動機器發電。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('end-ten-1', 'end-ten', 'cat', 2, '{"q":"十大建設是哪一類？","cats":["交通","重工業","能源"],"cards":[{"t":"中山高速公路","c":0},{"t":"北迴鐵路","c":0},{"t":"大煉鋼廠","c":1},{"t":"核能發電廠","c":2}],"why":"高速公路、鐵路是交通；煉鋼是重工業；核能發電廠是能源。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-ten-2', 'end-ten', 'mc', 1, '{"q":"十大建設是在什麼時候推動的？","opts":["1970 年代","1890 年代","2020 年代"],"a":0,"why":"十大建設大約在 1970 年代陸續動工、完成。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-ten-3', 'end-ten', 'tf', 2, '{"q":"十大建設裡，交通建設最多。","a":true,"why":"十項裡有六項是交通建設。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-hsr-1', 'end-hsr', 'mc', 1, '{"q":"臺灣高鐵在哪一年通車？","opts":["2007 年","1908 年","1979 年"],"a":0,"why":"高鐵 2007 年通車；1908 年是縱貫鐵路，1979 年是桃園機場啟用。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-hsr-2', 'end-hsr', 'mc', 2, '{"q":"「一日生活圈」是什麼意思？","opts":["南北來往很快，一天就能來回","每天只能出門一次","一天要繞臺灣一圈"],"a":0,"why":"高鐵讓臺北到高雄最快約一個半小時，一天就能來回。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-hsr-3', 'end-hsr', 'order', 3, '{"q":"把這些交通建設，照通車或完成的先後排好。","steps":["劉銘傳的鐵路（基隆到臺北）","縱貫鐵路（基隆到高雄）","中山高速公路","臺灣高鐵"],"why":"1891 年基隆到臺北的鐵路，1908 年縱貫鐵路，約 1978 年中山高速公路，2007 年高鐵。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-minority-1', 'end-minority', 'who', 2, '{"q":"社區開會投票時，誰的做法比較好？","says":[{"n":"小安","t":"先好好討論，也聽聽少數人的意見"},{"n":"阿強","t":"票多的就贏，不用管別人"},{"n":"小莉","t":"誰最大聲就聽誰的"}],"a":0,"why":"多數決是規則，但先討論、尊重少數，常能找到更多人接受的方法。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-minority-2', 'end-minority', 'tf', 1, '{"q":"民主社會裡，大家可以用投票表達意見。","a":true,"why":"投票是表達意見的方法，投票前也要好好討論。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-minority-3', 'end-minority', 'multi', 2, '{"q":"小朋友可以怎麼參與社區或學校的公共事務？（選兩個以上）","opts":["在班會上發言","提出建議","參加投票","偷偷破壞公物"],"a":[0,1,2],"why":"發言、提建議、投票都是公民參與；破壞公物是錯的。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('town-law-1', 'town-law', 'mc', 2, '{"q":"四種規範裡，哪一種違反了會被國家處罰？","opts":["法律","道德","風俗"],"a":0,"why":"法律由國家制定，有強制力，違反會被罰。道德、風俗靠大家自己遵守。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-law-2', 'town-law', 'mc', 3, '{"q":"鄰居半夜還用大喇叭唱歌，吵到大家睡不著，可以請誰來處理？","opts":["環保局或警察","郵差","老師"],"a":0,"why":"晚上太吵違反《噪音管制法》，可以請環保局或警察來量音量、勸導或開罰。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-law-3', 'town-law', 'cat', 2, '{"q":"這些事屬於哪一種規範？","cats":["法律","道德","風俗","宗教"],"cards":[{"t":"半夜太吵會被罰","c":0},{"t":"公車上讓座給長輩","c":1},{"t":"中秋節吃月餅、賞月","c":2},{"t":"進廟不踩門檻","c":3}],"why":"會被國家處罰的是法律；覺得應該幫助別人的是道德；從以前傳下來的習慣是風俗；信仰裡的規矩是宗教規範。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-moral-1', 'town-moral', 'tf', 2, '{"q":"在公車上不讓座，會被警察開罰單。","a":false,"why":"讓座是道德，不讓座不會被罰，但大家會覺得不好。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-moral-2', 'town-moral', 'who', 2, '{"q":"看到長輩站在公車上，誰的做法最好？","says":[{"n":"小雯","t":"有禮貌地讓座，或請別人讓座"},{"n":"阿哲","t":"打電話叫警察"},{"n":"小可","t":"在網路上罵坐著的人"}],"a":0,"why":"道德靠自己和互相提醒，好好說最有用。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-moral-3', 'town-moral', 'mc', 1, '{"q":"「看到別人需要幫忙，覺得應該幫忙」，這是哪一種規範？","opts":["道德","法律","宗教"],"a":0,"why":"道德是心裡覺得對、應該做的事。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-custom-1', 'town-custom', 'tf', 1, '{"q":"中秋節團圓、吃月餅，是從以前一直傳下來的風俗。","a":true,"why":"大家一年一年傳下來的習慣，叫做風俗。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-custom-2', 'town-custom', 'mc', 2, '{"q":"過年發紅包、端午節划龍舟，屬於哪一種規範？","opts":["風俗","法律","宗教"],"a":0,"why":"節日的習慣是從以前傳下來的，屬於風俗。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-custom-3', 'town-custom', 'who', 2, '{"q":"中秋節沒辦法回家團圓，會怎麼樣？誰說得對？","says":[{"n":"阿公","t":"不會被處罰，但很多人很重視團圓"},{"n":"小雯","t":"會被罰錢"},{"n":"阿明","t":"會被警察抓"}],"a":0,"why":"風俗做不到不會被罰，但大家很重視。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-religion-1', 'town-religion', 'mc', 2, '{"q":"參觀廟宇時不踩門檻、對神像拍照先問廟方，這屬於哪一種規範？","opts":["宗教規範","法律","風俗"],"a":0,"why":"對神明的規矩是宗教規範，信的人自己遵守，參觀的人也要尊重。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-religion-2', 'town-religion', 'who', 3, '{"q":"外國遊客在廟裡開閃光燈拍神像，誰的做法最好？","says":[{"n":"阿嬤","t":"好好告訴他廟裡的規矩"},{"n":"阿凱","t":"打 110 請警察抓他"},{"n":"小莉","t":"大聲罵他沒禮貌"}],"a":0,"why":"宗教規範不是法律，好好說明、互相尊重就好。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-kids-1', 'town-kids', 'tf', 2, '{"q":"幫爸爸買酒的話，未滿 18 歲也可以買。","a":false,"why":"法律規定不能把酒賣給未滿 18 歲的人，幫大人買也不行。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-kids-2', 'town-kids', 'cloze', 2, '{"q":"保護兒童和少年的法律。","text":"未滿{0}歲的人不能喝酒，菸更嚴格，未滿{1}歲都不行。","blanks":[{"opts":["18","12","15"],"a":0},{"opts":["20","16","18"],"a":0}],"why":"《兒童及少年福利與權益保障法》：酒是未滿 18 歲不行；菸害防制的規定，未滿 20 歲不能吸菸。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-kids-3', 'town-kids', 'mc', 2, '{"q":"遊戲盒子上標「輔 15」，意思是什麼？","opts":["未滿 15 歲不適合玩","要玩 15 個小時","15 元就可以買"],"a":0,"why":"遊戲、影片有分級，輔 15 是未滿 15 歲不適合。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-work-1', 'town-work', 'mc', 2, '{"q":"依照勞動基準法，幾歲以下原則上不能被僱用工作？","opts":["未滿 15 歲","未滿 10 歲","未滿 20 歲"],"a":0,"why":"未滿 15 歲原則上不能被僱用，保護孩子好好讀書長大。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-work-2', 'town-work', 'who', 3, '{"q":"14 歲的小雯想去飲料店打工，誰的建議最好？","says":[{"n":"姊姊","t":"先不要去，滿 15 歲、爸媽同意後再找合法的打工"},{"n":"阿傑","t":"偷偷去，不要讓人知道"},{"n":"老闆","t":"不用付錢，當作幫忙就好"}],"a":0,"why":"老闆僱用未滿 15 歲的人會被罰；15 歲以後打工也要爸媽同意。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-1', 'town-fraud', 'multi', 2, '{"q":"網路賣東西，哪些是詐騙常見的破綻？（選兩個以上）","opts":["價錢便宜得不合理","不能面交、一定要先匯款","一直催你快一點","有很多人留下好評、可以面交"],"a":[0,1,2],"why":"太便宜、先匯款、一直催，都是詐騙常見的手法。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-2', 'town-fraud', 'mc', 1, '{"q":"懷疑碰到詐騙，可以打哪一個電話問？","opts":["165 反詐騙專線","119","1999 生活熱線以外都不能打"],"a":0,"why":"165 是反詐騙諮詢專線。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-3', 'town-fraud', 'tf', 2, '{"q":"別人說要幫你處理帳戶，就可以把銀行密碼給他。","a":false,"why":"帳號密碼絕對不能給別人，給了錢可能全部被領走。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-privacy-1', 'town-privacy', 'mc', 2, '{"q":"同學要把有你的照片放上網，還寫出學校和全名，你不同意。依照法律，應該怎麼做？","opts":["請他先拿掉，問過大家同意再放","沒關係，大家都這樣","也放他的照片報復"],"a":0,"why":"每個人都有肖像權和隱私權，公開別人的照片和資料前要先問。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-privacy-2', 'town-privacy', 'tf', 1, '{"q":"別人的臉和個人資料受到法律保護，不能沒問過就公開。","a":true,"why":"這是肖像權和隱私權，受《民法》等法律保護。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-copy-1', 'town-copy', 'mc', 2, '{"q":"做報告用了網路上別人拍的照片，應該怎麼做？","opts":["寫清楚作者和出處","把作者的名字修掉","說是自己拍的"],"a":0,"why":"《著作權法》保護作者，做報告可以合理引用，但要寫出處。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-copy-2', 'town-copy', 'tf', 2, '{"q":"把別人的照片印很多張拿去賣，只要寫出處就沒問題。","a":false,"why":"合理引用是為了報告、教學；拿去賣錢就侵害著作權了。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('isles-pacific-1', 'isles-pacific', 'cat', 1, '{"q":"這些島在哪一片海上？","cats":["太平洋","臺灣海峽"],"cards":[{"t":"龜山島","c":0},{"t":"綠島","c":0},{"t":"蘭嶼","c":0},{"t":"澎湖","c":1},{"t":"小琉球","c":1}],"why":"龜山島、綠島、蘭嶼在臺灣東邊的太平洋；澎湖、小琉球在臺灣海峽。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-pacific-2', 'isles-pacific', 'mc', 2, '{"q":"蘭嶼是哪一族的家？","opts":["達悟族","邵族","西拉雅族"],"a":0,"why":"蘭嶼是達悟族的家，拼板舟是他們的特色。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-pacific-3', 'isles-pacific', 'tf', 1, '{"q":"從宜蘭頭城的海邊，看得到龜山島。","a":true,"why":"龜山島在宜蘭外海的太平洋上，像一隻浮在海上的烏龜。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-strait-1', 'isles-strait', 'mc', 1, '{"q":"澎湖群島在臺灣本島的哪一邊？","opts":["西邊的臺灣海峽","東邊的太平洋","北邊的東海"],"a":0,"why":"澎湖在臺灣海峽中間，由九十多座小島組成。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-strait-2', 'isles-strait', 'mc', 2, '{"q":"澎湖人用咾咕石堆成矮牆圍住菜園（菜宅），主要是為了擋什麼？","opts":["冬天強勁的東北季風","海裡的鯊魚","夏天的大太陽"],"a":0,"why":"澎湖冬天東北季風很強，菜宅可以擋風保護蔬菜。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-strait-3', 'isles-strait', 'tf', 1, '{"q":"小琉球是一座珊瑚礁島。","a":true,"why":"小琉球是臺灣附近島嶼中唯一的珊瑚礁島。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-near-1', 'isles-near', 'mc', 1, '{"q":"金門離哪裡比較近？","opts":["中國大陸","臺灣本島","菲律賓"],"a":0,"why":"金門緊靠中國大陸的廈門，離臺灣本島反而很遠。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-near-2', 'isles-near', 'who', 2, '{"q":"關於馬祖，誰說得對？","says":[{"n":"小安","t":"在臺灣西北邊，靠近中國大陸"},{"n":"阿美","t":"在臺灣東邊的太平洋上"},{"n":"小傑","t":"在臺灣南邊的巴士海峽"}],"a":0,"why":"馬祖在臺灣西北方，靠近中國大陸的福州。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('sky-neighbors-1', 'sky-neighbors', 'cloze', 1, '{"q":"臺灣四周的海。","text":"臺灣和中國大陸中間是{0}，和菲律賓中間是{1}。","blanks":[{"opts":["臺灣海峽","巴士海峽"],"a":0},{"opts":["臺灣海峽","巴士海峽"],"a":1}],"why":"西邊是臺灣海峽，南邊和菲律賓之間是巴士海峽。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-neighbors-2', 'sky-neighbors', 'mc', 2, '{"q":"從臺灣往北邊飛，下面這些國家裡最可能到的是哪一個？","opts":["韓國","菲律賓","澳洲"],"a":0,"why":"韓國在臺灣北方；菲律賓在南方；澳洲更南。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-hub-1', 'sky-hub', 'tf', 2, '{"q":"很多日本、韓國飛往東南亞的飛機，會經過臺灣附近的天空。","a":true,"why":"臺灣在東北亞和東南亞的中間，像一個中點站。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-hub-2', 'sky-hub', 'mc', 3, '{"q":"為什麼說臺灣是進出亞洲的「門戶」？","opts":["位在東北亞和東南亞航線的中間","臺灣是亞洲最大的國家","臺灣在亞洲的最北邊"],"a":0,"why":"很多航線經過臺灣附近，所以臺灣的位置很重要。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-world-1', 'sky-world', 'multi', 1, '{"q":"下面哪些是世界三大洋？（選三個）","opts":["太平洋","大西洋","印度洋","臺灣海峽"],"a":[0,1,2],"why":"三大洋是太平洋、大西洋、印度洋；臺灣海峽是一個海峽。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-world-2', 'sky-world', 'mc', 2, '{"q":"從臺灣坐船要去歐洲，通常會經過哪一片大洋？","opts":["印度洋","北冰洋","大西洋的北邊"],"a":0,"why":"往歐洲的船會往西南穿過麻六甲海峽，經過印度洋。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-world-3', 'sky-world', 'tf', 1, '{"q":"從臺灣往東橫越太平洋，可以到美洲。","a":true,"why":"美洲在太平洋的東邊。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('post-care-1', 'post-care', 'mc', 2, '{"q":"去太魯閣的落石區，應該怎麼做？","opts":["戴安全帽、不停留","在峭壁下野餐","撿大理石帶回家"],"a":0,"why":"峽谷會落石，戴安全帽、快速通過；國家公園的石頭也不能帶走。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-care-2', 'post-care', 'multi', 2, '{"q":"到日月潭玩，哪些做法對環境比較好？（選兩個以上）","opts":["搭公車或騎腳踏車","自己的垃圾帶走","少用一次性餐具","把垃圾丟進湖裡"],"a":[0,1,2],"why":"少開車、少垃圾，湖和空氣都會比較乾淨。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-care-3', 'post-care', 'who', 3, '{"q":"颱風天快到了，大家想去清水斷崖。誰的想法最安全？","says":[{"n":"小雯","t":"颱風天不要上山，出發前看路況"},{"n":"阿凱","t":"去斷崖邊看大浪最刺激"},{"n":"小宇","t":"開快一點，趕在颱風前衝過去"}],"a":0,"why":"颱風、大雨容易坍方落石，安全最重要。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-local-1', 'post-local', 'mc', 2, '{"q":"新竹新埔曬柿餅，靠的是秋冬哪一種風？","opts":["九降風（又乾又強的東北季風）","夏天又濕又熱的西南季風","夏秋常常帶來大雨的颱風"],"a":0,"why":"秋冬的九降風又乾又強，最適合把柿子曬成柿餅。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-local-2', 'post-local', 'tf', 1, '{"q":"新埔是客家庄，曬柿餅是當地傳下來的產業。","a":true,"why":"客家人很早就在新埔曬柿餅，一代傳一代。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-local-3', 'post-local', 'mc', 3, '{"q":"傳統產業的人越來越少，下面哪一個方法比較能讓它傳下去？","opts":["辦體驗活動，讓更多人認識、買在地產品","不管它，讓它慢慢消失","全部換成跟別的地方一樣的東西"],"a":0,"why":"結合觀光和產業，讓更多人認識，傳統才傳得下去。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('sci-camo-1', 'sci-camo', 'mc', 1, '{"q":"枯葉蝶收起翅膀時像什麼，讓天敵找不到牠？","opts":["一片枯葉","一朵紅花","一顆石頭"],"a":0,"why":"枯葉蝶收起翅膀時，形狀和顏色都像枯葉，這就是偽裝。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-camo-2', 'sci-camo', 'tf', 2, '{"q":"枯葉蝶停在落葉堆裡不動，比較不容易被天敵發現。","a":true,"why":"牠的樣子和落葉很像，不動的時候更難被看出來。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-camo-3', 'sci-camo', 'who', 3, '{"q":"為什麼很多動物身上的顏色，和住的地方很像？誰說得對？","says":[{"n":"斑斑","t":"這樣比較不容易被天敵或獵物發現"},{"n":"小樹","t":"因為牠們喜歡那個顏色"},{"n":"阿光","t":"因為顏色會被太陽曬掉"}],"a":0,"why":"和環境相像的顏色叫保護色，可以躲避天敵，也能偷偷接近獵物。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-team-1', 'sci-ant-team', 'cat', 2, '{"q":"螞蟻窩裡，誰負責什麼工作？","cats":["蟻后","工蟻","兵蟻"],"cards":[{"t":"產卵","c":0},{"t":"找食物、搬東西","c":1},{"t":"照顧卵和幼蟲","c":1},{"t":"守住蟻窩","c":2}],"why":"蟻后負責產卵；工蟻找食物、搬東西、照顧幼蟲；兵蟻守衛蟻窩。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-team-2', 'sci-ant-team', 'tf', 1, '{"q":"螞蟻是群體生活、分工合作的動物。","a":true,"why":"一個蟻窩裡有蟻后、工蟻、兵蟻，各做各的工作。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-team-3', 'sci-ant-team', 'mc', 2, '{"q":"一塊很大的餅乾，螞蟻怎麼把它搬回窩？","opts":["很多隻工蟻一起搬","蟻后自己搬","等餅乾自己滾進去"],"a":0,"why":"工蟻會找同伴一起合作，把大的食物搬回窩。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-talk-1', 'sci-ant-talk', 'multi', 2, '{"q":"螞蟻用哪些方法傳遞消息？（選兩個）","opts":["觸角互相碰觸","在地上留下氣味","大聲叫","揮手打招呼"],"a":[0,1],"why":"螞蟻用觸角互碰，也會在路上留下氣味，同伴聞著氣味就能找到路。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-talk-2', 'sci-ant-talk', 'mc', 3, '{"q":"一排螞蟻走成一條線去找食物，最可能是因為什麼？","opts":["跟著前面同伴留下的氣味走","牠們看得到很遠的食物","有人在前面帶路"],"a":0,"why":"找到食物的螞蟻會留下氣味，後面的同伴跟著氣味走，就排成一條線。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-rust-why-1', 'sci-rust-why', 'multi', 2, '{"q":"鐵要碰到哪些東西，久了才會生鏽？（選兩個）","opts":["水","空氣","沙子","光"],"a":[0,1],"why":"鐵同時碰到水和空氣（氧氣），久了就會生鏽。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-why-2', 'sci-rust-why', 'mc', 2, '{"q":"同樣的鐵釘，放在哪裡最快生鏽？","opts":["又濕又鹹的海邊","乾燥的抽屜裡","密封的乾燥罐裡"],"a":0,"why":"海邊潮濕又有鹽分，鐵生鏽得更快。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-why-3', 'sci-rust-why', 'tf', 1, '{"q":"放在乾燥地方的鐵，比放在潮濕地方的鐵容易生鏽。","a":false,"why":"潮濕的地方有很多水氣，鐵比較容易生鏽。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-stop-1', 'sci-rust-stop', 'multi', 2, '{"q":"下面哪些方法可以防止鐵生鏽？（選兩個以上）","opts":["保持乾燥","塗一層油","上油漆","常常泡在鹽水裡"],"a":[0,1,2],"why":"防鏽就是把鐵和水、空氣隔開：保持乾燥、塗油、上油漆。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-stop-2', 'sci-rust-stop', 'order', 3, '{"q":"鐵門有點濕又開始生鏽，排出修理的順序。","steps":["用乾布把水擦乾","把鏽刷掉","塗上油漆把鐵包起來"],"why":"要先擦乾、去鏽，再上油漆；在濕的鐵上直接塗油漆，水分還會被包在裡面。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-stop-3', 'sci-rust-stop', 'who', 2, '{"q":"腳踏車的鏈條要怎麼保養才不容易生鏽？誰說得對？","says":[{"n":"鐵叔","t":"擦乾淨以後上一點油"},{"n":"小海","t":"每天用水沖"},{"n":"阿浪","t":"放在雨裡比較乾淨"}],"a":0,"why":"油可以把鐵和水、空氣隔開，所以鏈條要擦乾淨再上油。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-vibrate-1', 'sci-vibrate', 'tf', 1, '{"q":"聲音是物體振動產生的。","a":true,"why":"敲鼓、撥弦、說話時，發聲的東西都在振動。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-vibrate-2', 'sci-vibrate', 'mc', 2, '{"q":"敲完音叉，把它輕輕放進水裡，會看到什麼？","opts":["水花被振動濺起來","水變成熱水","什麼都不會發生"],"a":0,"why":"音叉發聲時在振動，碰到水就會把水濺起來。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-vibrate-3', 'sci-vibrate', 'mc', 2, '{"q":"用手按住正在響的鼓皮，聲音會怎樣？","opts":["聲音停下來","聲音變更大","聲音變更高"],"a":0,"why":"按住鼓皮，鼓皮不能振動，聲音就停了。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-pitch-1', 'sci-pitch', 'cloze', 2, '{"q":"調樂器的聲音。","text":"弦拉得越{0}，聲音越高；鼓皮繃得越{1}，聲音也越高。","blanks":[{"opts":["緊","鬆"],"a":0},{"opts":["緊","鬆"],"a":0}],"why":"弦和鼓皮越緊，振動越快，聲音越高。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-pitch-2', 'sci-pitch', 'order', 3, '{"q":"三個一樣的玻璃瓶裝了不同多的水，用筷子敲。從最低的聲音排到最高。","steps":["水最多的瓶子","水一半的瓶子","水最少的瓶子"],"why":"用敲的時候，水越多聲音越低，水越少聲音越高。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-pitch-3', 'sci-pitch', 'tf', 2, '{"q":"用筷子敲裝水的玻璃瓶，水越多，聲音越高。","a":false,"why":"敲瓶子時，水越多聲音越低。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-noise-1', 'sci-noise', 'multi', 2, '{"q":"下面哪些方法可以減少噪音？（選兩個以上）","opts":["掛上隔音布、關窗","離聲音來源遠一點","晚上把音量轉小","把喇叭對準鄰居"],"a":[0,1,2],"why":"隔音、遠離聲音來源、降低音量都能減少噪音。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-noise-2', 'sci-noise', 'mc', 1, '{"q":"什麼樣的聲音是「噪音」？","opts":["讓人覺得吵、不舒服的聲音","所有很高的聲音","所有音樂的聲音"],"a":0,"why":"吵到別人、讓人不舒服的聲音就是噪音，好聽的音樂太大聲也可能變噪音。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-sun-1', 'sci-sun', 'cloze', 1, '{"q":"太陽在天空的位置。","text":"太陽早上從{0}邊升起，傍晚從{1}邊落下。","blanks":[{"opts":["東","西","南"],"a":0},{"opts":["東","西","北"],"a":1}],"why":"太陽東升西落。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sun-2', 'sci-sun', 'mc', 2, '{"q":"一天裡，太陽什麼時候在天空最高的地方？","opts":["中午","早上","傍晚"],"a":0,"why":"太陽早上低，中午最高，傍晚又變低。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sun-3', 'sci-sun', 'order', 2, '{"q":"排出一天裡太陽的位置變化。","steps":["從東邊升起","中午在天空最高","從西邊落下"],"why":"太陽早上從東邊升起，中午最高，傍晚從西邊落下。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-shadow-1', 'sci-shadow', 'mc', 2, '{"q":"早上太陽在東邊，地上的影子會倒向哪一邊？","opts":["西邊","東邊","影子不見了"],"a":0,"why":"影子在太陽的反方向，太陽在東，影子就倒向西。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-shadow-2', 'sci-shadow', 'tf', 2, '{"q":"一天裡，中午的影子最短。","a":true,"why":"中午太陽最高，影子最短；早上和傍晚太陽低，影子長。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-shadow-3', 'sci-shadow', 'who', 3, '{"q":"在臺灣，中午時影子大多朝向哪一邊？誰說得對？","says":[{"n":"帝雉台長","t":"大多朝向北邊，因為太陽在南邊的天空"},{"n":"小星","t":"朝向東邊"},{"n":"阿月","t":"中午沒有影子"}],"a":0,"why":"臺灣一年裡大部分的日子，中午太陽在南邊的天空，所以影子朝北。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sundial-1', 'sci-sundial', 'mc', 2, '{"q":"日晷是看什麼來知道時間？","opts":["影子的位置","星星的顏色","風吹的方向"],"a":0,"why":"太陽移動，影子跟著移動，看影子落在哪個刻度就知道時間。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sundial-2', 'sci-sundial', 'mc', 3, '{"q":"日晷的影子從西邊慢慢轉到東邊，表示時間怎麼過？","opts":["從早上到下午","從下午到早上","時間沒有變"],"a":0,"why":"早上太陽在東、影子朝西；下午太陽在西、影子朝東。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft')
